<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from "vue";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips, ShowTextTipsError, ShowTextTipsInfo, type GlobalProperties } from "@/util/tips";
import { useBreakpoint } from "@/composables/useBreakpoint";
import {
  GetEnrichAliasList,
  GetEnrichCallList,
  GetEnrichConsistency,
  GetEnrichOverview,
  GetEnrichReviewList,
  GetEnrichStateList,
  GetEnrichTagList,
  GetEnrichTagSearch,
  GetEnrichWorkerConfig,
  PostEnrichAliasAdd,
  PostEnrichAliasDelete,
  PostEnrichBackfill,
  PostEnrichGoldenSet,
  PostEnrichRejudge,
  PostEnrichRejudgeFailed,
  PostEnrichReviewSet,
  PostEnrichTagApprove,
  PostEnrichTagDeprecate,
  PostEnrichTagMerge,
  PostEnrichTagReactivate,
} from "@/apis/problem-enrichment";
import type {
  EnrichCallItem,
  EnrichConsistencyReport,
  EnrichOverview,
  EnrichReviewItem,
  EnrichStateItem,
  EnrichStateStatus,
  EnrichTag,
  EnrichWorkerConfig,
  TagAlias,
} from "@/types/problem-enrichment";
import { TagStatus } from "@/types/problem-enrichment";
import { handleGotoProblem } from "@/util/router";
import EnrichCuratorDrawer from "./EnrichCuratorDrawer.vue";

const globalProperties = useCurrentInstance().globalProperties as GlobalProperties;
const { isMobile } = useBreakpoint();

// ───────────────────────── 通用 ─────────────────────────

const activeTab = ref("state");
const pageSize = isMobile.value ? 20 : 50;

const stateStatusOptions = [
  { label: "未处理", value: 0 },
  { label: "排队", value: 1 },
  { label: "处理中", value: 2 },
  { label: "成功", value: 3 },
  { label: "失败", value: 4 },
];

const stateStatusText: Record<number, string> = {
  0: "未处理",
  1: "排队",
  2: "处理中",
  3: "成功",
  4: "失败",
};

const stateStatusTheme: Record<number, string> = {
  0: "default",
  1: "warning",
  2: "primary",
  3: "success",
  4: "danger",
};

// worker 阶段中文化
const stageText: Record<string, string> = {
  queued: "排队中",
  fingerprint: "指纹比对",
  summary: "摘要",
  tags: "标签",
  difficulty: "难度",
  quality: "质量",
  suggestion: "改进建议",
  finalize: "收尾落库",
  dry_run: "干跑",
};

const callStatusText: Record<string, string> = {
  running: "进行中",
  success: "成功",
  fail: "失败",
};
const callStatusTheme: Record<string, string> = {
  running: "primary",
  success: "success",
  fail: "danger",
};

const tagStatusText: Record<number, string> = {
  0: "候选",
  1: "正式",
  2: "已合并",
  3: "已归档",
};

const tagStatusTheme: Record<number, string> = {
  0: "warning",
  1: "success",
  2: "default",
  3: "danger",
};

const taskTypeText: Record<string, string> = {
  summary: "摘要",
  tags: "标签",
  difficulty: "难度",
  quality: "质量",
  suggestion: "建议",
};

const visibilityText: Record<string, string> = {
  public: "公开",
  internal: "内部",
  sensitive: "敏感",
};

const reviewStatusText: Record<string, string> = {
  "": "—",
  pending: "待审核",
  approved: "已通过",
  rejected: "已驳回",
};

const gradeName = (grade: number): string => ["", "入门", "普及", "提高", "省选", "NOI"][grade] ?? "—";
const fmtTime = (s?: string) => (s ? new Date(s).toLocaleString() : "—");
const fmtSec = (ms: number) => (ms >= 1000 ? `${(ms / 1000).toFixed(1)}s` : `${ms}ms`);
// 审核卡片里取 payload（模板里放宽类型）
const pp = (item: EnrichReviewItem): any => item.payload ?? {};

// ───────────────────────── Tab1：运维总览 + 状态监控 ─────────────────────────

const workerConfig = ref<EnrichWorkerConfig | null>(null);
const overview = ref<EnrichOverview | null>(null);
const stateList = ref<EnrichStateItem[]>([]);
const stateTotal = ref(0);
const statePage = ref(1);
const stateFilter = ref<number[]>([]);
const stateLoading = ref(false);
const backfilling = ref(false);
const autoRefresh = ref(false);
let stateTimer: ReturnType<typeof setInterval> | null = null;

const statePagination = computed(() => ({
  current: statePage.value,
  pageSize,
  total: stateTotal.value,
  defaultCurrent: 1,
  defaultPageSize: pageSize,
}));

const stateColumns = [
  { colKey: "problem_id", title: "题目", minWidth: 160 },
  { colKey: "status", title: "状态", width: 90 },
  { colKey: "stage", title: "阶段", width: 100 },
  { colKey: "worker", title: "Worker", width: 100 },
  { colKey: "attempt", title: "尝试", width: 60 },
  { colKey: "message", title: "信息", minWidth: 160 },
  { colKey: "modify_time", title: "更新时间", width: 170 },
  { colKey: "operation", title: "操作", width: 210, fixed: "right" as const },
];

const tagColumns = [
  { colKey: "name", title: "标签", minWidth: 160 },
  { colKey: "status", title: "状态", width: 150 },
  { colKey: "usage_count", title: "命中题数", width: 100 },
  { colKey: "operation", title: "操作", width: 280, fixed: "right" as const },
];

const consistencyColumns = [
  { colKey: "problem_id", title: "题目", width: 120 },
  { colKey: "golden", title: "黄金集档位", width: 130 },
  { colKey: "latest_ai", title: "最新 AI 档位", width: 140 },
  { colKey: "within_one", title: "是否 ±1 档内", width: 140 },
];

const configRows = computed(() => {
  const c = workerConfig.value;
  if (!c) {
    return [];
  }
  if (c.Tier === "judge") {
    return [
      { label: "运行位置", value: "judge 评测进程（常驻）" },
      { label: "配置位置", value: "judge 配置 ai.problem-enrichment" },
      { label: "实时进度", value: "见下方总览、状态列表与调用账本" },
    ];
  }
  return [
    { label: "总开关", value: c.Enabled ? "启用" : "关闭" },
    { label: "干跑模式", value: c.DryRun ? "干跑（不调 LLM）" : "真实调用" },
    { label: "模型", value: c.Model || "（未配置）" },
    { label: "轮询间隔", value: `${Math.round((c.Interval ?? 0) / 1e9)} 秒` },
    { label: "每轮题数", value: String(c.BatchSize ?? 0) },
    { label: "最大尝试", value: String(c.MaxAttempt ?? 0) },
    { label: "卡死回收", value: `${Math.round((c.StaleTimeout ?? 0) / 60e9)} 分钟` },
    { label: "每日 token 上限", value: (c.DailyTokenLimit ?? 0) > 0 ? String(c.DailyTokenLimit) : "不限" },
    { label: "每日题数上限", value: (c.DailyProblemLimit ?? 0) > 0 ? String(c.DailyProblemLimit) : "不限" },
    { label: "候选自动晋升阈值", value: `${c.CandidatePromoteUsage ?? 0} 题` },
  ];
});

const fetchWorkerConfig = async () => {
  try {
    const res = await GetEnrichWorkerConfig();
    if (res.code === 0) {
      workerConfig.value = res.data;
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
  }
};

const fetchOverview = async () => {
  try {
    const res = await GetEnrichOverview();
    if (res.code === 0) {
      overview.value = res.data;
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
  }
};

const fetchStateList = async () => {
  stateLoading.value = true;
  try {
    const res = await GetEnrichStateList(
      stateFilter.value.length > 0 ? (stateFilter.value as EnrichStateStatus[]) : null,
      statePage.value,
      pageSize
    );
    if (res.code === 0) {
      stateList.value = res.data.list;
      stateTotal.value = res.data.total;
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  } finally {
    stateLoading.value = false;
  }
};

const onStatePageChange = (info: { current: number }) => {
  statePage.value = info.current;
  fetchStateList();
};

const onStateFilterChange = () => {
  statePage.value = 1;
  fetchStateList();
};

// 点击总览状态卡快速筛选
const quickFilter = (status: number | null) => {
  stateFilter.value = status == null ? [] : [status];
  statePage.value = 1;
  fetchStateList();
};

const handleBackfill = async () => {
  backfilling.value = true;
  try {
    const res = await PostEnrichBackfill();
    if (res.code === 0) {
      ShowTextTipsInfo(globalProperties, `补插完成，新增 ${res.data.inserted} 行`);
      fetchStateList();
      fetchOverview();
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  } finally {
    backfilling.value = false;
  }
};

// 手动重判（强制，可解救处理中卡死题）
const handleRejudge = async (row: EnrichStateItem) => {
  try {
    const res = await PostEnrichRejudge(row.problem_id);
    if (res.code === 0) {
      ShowTextTipsInfo(globalProperties, "已强制重新入队，judge 将重新处理");
      await fetchStateList();
      fetchOverview();
      openCallDrawer(row);
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  }
};

// 一键重判全部失败题
const rejudgingFailed = ref(false);
const handleRejudgeFailed = async () => {
  rejudgingFailed.value = true;
  try {
    const res = await PostEnrichRejudgeFailed();
    if (res.code === 0) {
      ShowTextTipsInfo(globalProperties, `已将 ${res.data.reset} 道失败题重新入队`);
      await fetchStateList();
      fetchOverview();
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  } finally {
    rejudgingFailed.value = false;
  }
};

// ── 调用账本抽屉 ──
const callDrawerVisible = ref(false);
const callProblemId = ref(0);
const callList = ref<EnrichCallItem[]>([]);
const callLoading = ref(false);
const callStateSnapshot = ref<EnrichStateItem | null>(null);
let callTimer: ReturnType<typeof setInterval> | null = null;

const callHeaderTitle = computed(() => {
  const row = stateList.value.find((x) => x.problem_id === callProblemId.value);
  return row ? `调用账本 · ${row.problem_key || callProblemId.value} ${row.problem_title ?? ""}` : `调用账本 · 题目 #${callProblemId.value}`;
});
// 行可能因重判后状态变化而离开当前筛选页，用打开时的快照兜底展示
const callStateRow = computed(
  () => stateList.value.find((x) => x.problem_id === callProblemId.value) ?? callStateSnapshot.value
);

const fetchCalls = async () => {
  if (!callProblemId.value) {
    return;
  }
  callLoading.value = true;
  try {
    const res = await GetEnrichCallList({ problem_id: callProblemId.value, page: 1, page_size: 100 });
    if (res.code === 0) {
      callList.value = res.data.list;
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
  } finally {
    callLoading.value = false;
  }
};

const stopCallPolling = () => {
  if (callTimer) {
    clearInterval(callTimer);
    callTimer = null;
  }
};

const openCallDrawer = (row: EnrichStateItem) => {
  callProblemId.value = row.problem_id;
  callStateSnapshot.value = row;
  callList.value = [];
  callDrawerVisible.value = true;
  fetchCalls();
  fetchStateList();
  stopCallPolling();
  callTimer = setInterval(() => {
    fetchCalls();
    fetchStateList();
    fetchOverview();
  }, 4000);
};

watch(callDrawerVisible, (v) => {
  if (!v) {
    stopCallPolling();
    fetchStateList();
    fetchOverview();
  }
});

// 自动刷新（运维总览 + 列表，30s）
watch(autoRefresh, (on) => {
  if (on && activeTab.value === "state") {
    stateTimer = setInterval(() => {
      fetchOverview();
      fetchStateList();
    }, 30000);
  } else if (stateTimer) {
    clearInterval(stateTimer);
    stateTimer = null;
  }
});

// ── 人工标注 / 校正抽屉（状态页入口） ──
const curatorVisible = ref(false);
const curatorProblemId = ref(0);
const curatorTaskType = ref("summary");
const curatorReviewMode = ref(false);

const openCuratorFromState = (row: EnrichStateItem, taskType = "summary") => {
  curatorProblemId.value = row.problem_id;
  curatorTaskType.value = taskType;
  curatorReviewMode.value = false;
  curatorVisible.value = true;
};

// 抽屉显隐变化：非审核模式关闭时刷新运维台
const onCuratorVisibleChange = (v: boolean) => {
  curatorVisible.value = v;
  if (!v && !curatorReviewMode.value) {
    fetchStateList();
    fetchOverview();
  }
};

// ───────────────────────── Tab2：词表治理 ─────────────────────────

const tagList = ref<EnrichTag[]>([]);
const tagTotal = ref(0);
const tagPage = ref(1);
const tagFilter = ref<number[]>([0, 1, 3]);
const tagLoading = ref(false);
const tagMap = ref<Map<number, EnrichTag>>(new Map());

// 合并对话框（目标远程搜索，不再只含当前页）
const mergeDialogVisible = ref(false);
const mergeSource = ref<EnrichTag | null>(null);
const mergeTargetId = ref<number | undefined>(undefined);
const mergeTargetOptions = ref<{ label: string; value: number }[]>([]);
const mergeSearching = ref(false);
const mergeSubmitting = ref(false);

// 别名对话框
const aliasDialogVisible = ref(false);
const aliasTag = ref<EnrichTag | null>(null);
const aliasList = ref<TagAlias[]>([]);
const aliasLoading = ref(false);
const aliasInput = ref("");
const aliasSubmitting = ref(false);

const tagPagination = computed(() => ({
  current: tagPage.value,
  pageSize,
  total: tagTotal.value,
  defaultCurrent: 1,
  defaultPageSize: pageSize,
}));

const fetchTagList = async () => {
  tagLoading.value = true;
  try {
    const res = await GetEnrichTagList(tagFilter.value.length > 0 ? tagFilter.value : null, tagPage.value, pageSize);
    if (res.code === 0) {
      tagList.value = res.data.list;
      tagTotal.value = res.data.total;
      const m = new Map<number, EnrichTag>();
      res.data.list.forEach((t) => m.set(t.id, t));
      tagMap.value = m;
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  } finally {
    tagLoading.value = false;
  }
};

const onTagPageChange = (info: { current: number }) => {
  tagPage.value = info.current;
  fetchTagList();
};

const onTagFilterChange = () => {
  tagPage.value = 1;
  fetchTagList();
};

const handleApproveTag = async (tag: EnrichTag) => {
  const res = await PostEnrichTagApprove(tag.id);
  if (res.code === 0) {
    ShowTextTipsInfo(globalProperties, "已批准为正式标签");
    fetchTagList();
  } else {
    ShowErrorTips(globalProperties, res.code);
  }
};

const handleDeprecateTag = async (tag: EnrichTag) => {
  const res = await PostEnrichTagDeprecate(tag.id);
  if (res.code === 0) {
    ShowTextTipsInfo(globalProperties, "已归档");
    fetchTagList();
  } else {
    ShowErrorTips(globalProperties, res.code);
  }
};

const handleReactivateTag = async (tag: EnrichTag) => {
  const res = await PostEnrichTagReactivate(tag.id);
  if (res.code === 0) {
    ShowTextTipsInfo(globalProperties, "已恢复为正式标签");
    fetchTagList();
  } else {
    ShowErrorTips(globalProperties, res.code);
  }
};

// 合并目标远程搜索
const searchMergeTarget = async (keyword: string) => {
  mergeSearching.value = true;
  try {
    const res = await GetEnrichTagSearch(keyword, 20, [TagStatus.Active]);
    if (res.code === 0) {
      mergeTargetOptions.value = res.data.list
        .filter((t) => t.id !== mergeSource.value?.id)
        .map((t) => ({ label: `${t.name}（命中 ${t.usage_count}）`, value: t.id }));
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
  } finally {
    mergeSearching.value = false;
  }
};

const openMergeDialog = (tag: EnrichTag) => {
  mergeSource.value = tag;
  mergeTargetId.value = undefined;
  mergeTargetOptions.value = [];
  mergeDialogVisible.value = true;
  searchMergeTarget("");
};

const handleMergeSubmit = async () => {
  if (!mergeSource.value || !mergeTargetId.value) {
    return;
  }
  mergeSubmitting.value = true;
  try {
    const res = await PostEnrichTagMerge(mergeSource.value.id, mergeTargetId.value);
    if (res.code === 0) {
      ShowTextTipsInfo(globalProperties, "合并完成，历史关联已保留");
      mergeDialogVisible.value = false;
      fetchTagList();
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  } finally {
    mergeSubmitting.value = false;
  }
};

const mergedTargetName = (row: EnrichTag) => {
  if (row.merged_to_id == null) {
    return "";
  }
  return tagMap.value.get(row.merged_to_id)?.name ?? `#${row.merged_to_id}`;
};

const openAliasDialog = async (tag: EnrichTag) => {
  aliasTag.value = tag;
  aliasInput.value = "";
  aliasDialogVisible.value = true;
  aliasLoading.value = true;
  try {
    const res = await GetEnrichAliasList(tag.id);
    if (res.code === 0) {
      aliasList.value = res.data;
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  } finally {
    aliasLoading.value = false;
  }
};

const handleAliasAdd = async () => {
  if (!aliasTag.value || !aliasInput.value.trim()) {
    return;
  }
  aliasSubmitting.value = true;
  try {
    const res = await PostEnrichAliasAdd(aliasTag.value.id, aliasInput.value.trim());
    if (res.code === 0) {
      ShowTextTipsInfo(globalProperties, "别名已登记");
      aliasInput.value = "";
      const refresh = await GetEnrichAliasList(aliasTag.value.id);
      if (refresh.code === 0) {
        aliasList.value = refresh.data;
      }
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  } finally {
    aliasSubmitting.value = false;
  }
};

const handleAliasDelete = async (id: number) => {
  const res = await PostEnrichAliasDelete(id);
  if (res.code === 0) {
    ShowTextTipsInfo(globalProperties, "别名已删除");
    if (aliasTag.value) {
      const refresh = await GetEnrichAliasList(aliasTag.value.id);
      if (refresh.code === 0) {
        aliasList.value = refresh.data;
      }
    }
  } else {
    ShowErrorTips(globalProperties, res.code);
  }
};

// ───────────────────────── Tab3：标注审核（键盘流 + 人工校正） ─────────────────────────

const reviewList = ref<EnrichReviewItem[]>([]);
const reviewTotal = ref(0);
const reviewPage = ref(1);
const reviewLoading = ref(false);
const reviewCursor = ref(0);
const reviewSubmitting = ref(false);
const rawDialogVisible = ref(false);
const rawDialogContent = ref<EnrichReviewItem | null>(null);

// 驳回理由对话框
const rejectDialogVisible = ref(false);
const rejectNote = ref("");
const rejectTargetId = ref(0);

const currentReview = computed(() => reviewList.value[reviewCursor.value] ?? null);

const fetchReviewList = async () => {
  reviewLoading.value = true;
  try {
    const res = await GetEnrichReviewList(reviewPage.value, pageSize);
    if (res.code === 0) {
      reviewList.value = res.data.list;
      reviewTotal.value = res.data.total;
      reviewCursor.value = 0;
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  } finally {
    reviewLoading.value = false;
  }
};

const onReviewPageChange = async (info: { current: number }) => {
  reviewPage.value = info.current;
  await fetchReviewList();
};

const prettyJSON = (obj: unknown): string => {
  try {
    return JSON.stringify(obj, null, 2);
  } catch {
    return String(obj);
  }
};

// 从待审队列移除一条（审核动作完成后）
const removeReviewItem = (id: number) => {
  const idx = reviewList.value.findIndex((x) => x.id === id);
  if (idx >= 0) {
    reviewList.value.splice(idx, 1);
    reviewTotal.value -= 1;
    if (reviewCursor.value >= reviewList.value.length && reviewCursor.value > 0) {
      reviewCursor.value -= 1;
    }
  }
};

// 直接通过（不修改）
const reviewApprove = async (item: EnrichReviewItem) => {
  if (reviewSubmitting.value) {
    return;
  }
  reviewSubmitting.value = true;
  try {
    const res = await PostEnrichReviewSet(item.id, "approved");
    if (res.code === 0) {
      ShowTextTipsInfo(globalProperties, "已通过");
      removeReviewItem(item.id);
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  } finally {
    reviewSubmitting.value = false;
  }
};

const openRejectDialog = (item: EnrichReviewItem) => {
  rejectTargetId.value = item.id;
  rejectNote.value = "";
  rejectDialogVisible.value = true;
};

const confirmReject = async () => {
  if (!rejectTargetId.value) {
    return;
  }
  reviewSubmitting.value = true;
  try {
    const res = await PostEnrichReviewSet(rejectTargetId.value, "rejected", rejectNote.value.trim());
    if (res.code === 0) {
      ShowTextTipsInfo(globalProperties, "已驳回");
      rejectDialogVisible.value = false;
      removeReviewItem(rejectTargetId.value);
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  } finally {
    reviewSubmitting.value = false;
  }
};

const toggleGolden = async (item: EnrichReviewItem) => {
  if (reviewSubmitting.value) {
    return;
  }
  reviewSubmitting.value = true;
  try {
    const res = await PostEnrichGoldenSet(item.id, !item.golden);
    if (res.code === 0) {
      item.golden = !item.golden;
      ShowTextTipsInfo(globalProperties, item.golden ? "已冻结为黄金集基准" : "已解除黄金集");
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  } finally {
    reviewSubmitting.value = false;
  }
};

const openRawDialog = (item: EnrichReviewItem) => {
  rawDialogContent.value = item;
  rawDialogVisible.value = true;
};

// ── 审核流：人工校正抽屉 ──
const openCuratorForReview = (item: EnrichReviewItem) => {
  curatorProblemId.value = item.problem_id;
  curatorTaskType.value = item.task_type;
  curatorReviewMode.value = true;
  curatorVisible.value = true;
};

// 校正保存后：移除该待审项；若要推进且本页还有下一条，自动打开
const onCuratorSaved = ({ taskType, advance }: { taskType: string; advance: boolean }) => {
  // 按实际保存的 problem + 类型定位待审项（用户可能在抽屉里切换过类型 tab）
  const idx = reviewList.value.findIndex(
    (x) => x.problem_id === curatorProblemId.value && x.task_type === taskType
  );
  if (idx >= 0) {
    reviewList.value.splice(idx, 1);
    reviewTotal.value -= 1;
  }
  if (advance && curatorReviewMode.value) {
    const next = reviewList.value[idx] ?? reviewList.value[idx - 1] ?? null;
    if (next) {
      openCuratorForReview(next);
      return;
    }
    curatorVisible.value = false;
    if (reviewTotal.value > 0) {
      ShowTextTipsInfo(globalProperties, "本页已审完，可翻页继续");
    }
  } else {
    fetchOverview();
  }
};

const onCuratorRejected = ({ annotationId }: { annotationId: number }) => {
  const idx = reviewList.value.findIndex((x) => x.id === annotationId);
  if (idx >= 0) {
    reviewList.value.splice(idx, 1);
    reviewTotal.value -= 1;
  }
  const next = reviewList.value[idx] ?? reviewList.value[idx - 1] ?? null;
  if (next) {
    openCuratorForReview(next);
  } else {
    curatorVisible.value = false;
  }
};

// 键盘流：A 通过 · X 驳回（填理由）· E 校正编辑 · G 黄金集 · ↑↓ 切换
const onReviewKeydown = (e: KeyboardEvent) => {
  if (
    activeTab.value !== "review" ||
    rawDialogVisible.value ||
    mergeDialogVisible.value ||
    aliasDialogVisible.value ||
    curatorVisible.value ||
    rejectDialogVisible.value
  ) {
    return;
  }
  const target = e.target as HTMLElement | null;
  if (target && ["INPUT", "TEXTAREA", "SELECT"].includes(target.tagName)) {
    return;
  }
  const item = currentReview.value;
  if (!item) {
    return;
  }
  if (e.key === "a" || e.key === "A") {
    e.preventDefault();
    reviewApprove(item);
  } else if (e.key === "x" || e.key === "X") {
    e.preventDefault();
    reviewCursor.value = reviewList.value.indexOf(item);
    openRejectDialog(item);
  } else if (e.key === "e" || e.key === "E") {
    e.preventDefault();
    reviewCursor.value = reviewList.value.indexOf(item);
    openCuratorForReview(item);
  } else if (e.key === "g" || e.key === "G") {
    e.preventDefault();
    toggleGolden(item);
  } else if (e.key === "ArrowDown") {
    e.preventDefault();
    if (reviewCursor.value < reviewList.value.length - 1) {
      reviewCursor.value += 1;
    }
  } else if (e.key === "ArrowUp") {
    e.preventDefault();
    if (reviewCursor.value > 0) {
      reviewCursor.value -= 1;
    }
  }
};

// ───────────────────────── Tab4：黄金集一致率 ─────────────────────────

const consistencyReport = ref<EnrichConsistencyReport | null>(null);
const consistencyLoading = ref(false);

const fetchConsistency = async () => {
  consistencyLoading.value = true;
  try {
    const res = await GetEnrichConsistency();
    if (res.code === 0) {
      consistencyReport.value = res.data;
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  } finally {
    consistencyLoading.value = false;
  }
};

// tab 切换时懒加载
const onTabChange = (name: string) => {
  activeTab.value = name;
  if (name === "state") {
    fetchWorkerConfig();
    fetchOverview();
    fetchStateList();
  } else if (name === "tag" && tagList.value.length === 0) {
    fetchTagList();
  } else if (name === "review") {
    fetchReviewList();
  } else if (name === "golden") {
    fetchConsistency();
  }
  if (name !== "state" && stateTimer) {
    clearInterval(stateTimer);
    stateTimer = null;
  }
};

const gotoProblem = (problemKey: string) => {
  if (problemKey) {
    handleGotoProblem(problemKey);
  }
};

onMounted(() => {
  fetchWorkerConfig();
  fetchOverview();
  fetchStateList();
  window.addEventListener("keydown", onReviewKeydown);
});

onBeforeUnmount(() => {
  window.removeEventListener("keydown", onReviewKeydown);
  stopCallPolling();
  if (stateTimer) {
    clearInterval(stateTimer);
  }
});
</script>

