              <t-col :xs="12" :sm="6" :md="3">
                <t-card class="metric-card" :class="{ 'metric-pass': consistencyReport.passed }">
                  <div class="metric-value">{{ (consistencyReport.within_one_rate * 100).toFixed(0) }}%</div>
                  <div class="metric-label">
                    ±1 档一致率（门槛 {{ (consistencyReport.threshold * 100).toFixed(0) }}%）
                  </div>
                </t-card>
              </t-col>
            </t-row>

            <t-tag :theme="consistencyReport.passed ? 'success' : 'warning'" variant="light" class="consistency-verdict">
              {{ consistencyReport.passed ? "达到自动生效门槛" : "未达门槛，难度标注仅提示不自动生效" }}
            </t-tag>

            <div v-if="consistencyReport.details.length > 0" class="enrich-table-wrap">
              <t-table
                :data="consistencyReport.details"
                :columns="consistencyColumns"
                row-key="problem_id"
                table-layout="auto"
                :max-height="isMobile ? 360 : 520"
              >
                <template #problem_id="{ row }">
                  <span>#{{ row.problem_id }}</span>
                </template>
                <template #golden="{ row }">{{ gradeName(row.golden) }}</template>
                <template #latest_ai="{ row }">{{ row.latest_ai < 0 ? "缺失" : gradeName(row.latest_ai) }}</template>
                <template #within_one="{ row }">
                  <t-tag :theme="row.within_one ? 'success' : 'danger'" variant="light">
                    {{ row.within_one ? "±1 档内" : "偏差>1" }}
                  </t-tag>
                </template>
              </t-table>
            </div>
          </div>
        </t-tab-panel>
      </t-tabs>
    </t-card>

    <!-- 调用账本抽屉 -->
    <t-drawer v-model:visible="callDrawerVisible" :header="callHeaderTitle" size="720px" :footer="false">
      <div v-if="callStateRow" class="call-state">
        <t-space size="small" wrap>
          <t-tag :theme="stateStatusTheme[callStateRow.status]" variant="light">
            {{ stateStatusText[callStateRow.status] }}
          </t-tag>
          <t-tag variant="outline">{{ stageText[callStateRow.stage ?? ""] || callStateRow.stage || "—" }}</t-tag>
          <t-tag v-if="callStateRow.worker" variant="outline">{{ callStateRow.worker }}</t-tag>
          <span class="review-meta">尝试 {{ callStateRow.attempt }} · 更新 {{ fmtTime(callStateRow.modify_time) }}</span>
        </t-space>
        <t-alert v-if="callStateRow.message" theme="danger" class="ov-alert" :message="callStateRow.message" />
        <t-popconfirm
          content="强制重新入队并重新跑完整流水线（人工已定稿的类型会保留），确定？"
          @confirm="handleRejudge(callStateRow)"
        >
          <t-button size="small" theme="primary" variant="outline" class="call-rejudge-btn">手动重判此题</t-button>
        </t-popconfirm>
        <t-button size="small" theme="success" variant="outline" @click="openCuratorFromState(callStateRow)">
          人工标注
        </t-button>
      </div>
      <t-loading :loading="callLoading && callList.length === 0" size="small">
        <div v-if="callList.length === 0" class="enrich-empty">暂无调用记录（重判后每 4 秒自动刷新）</div>
        <div v-for="c in callList" :key="c.id" class="call-row">
          <div class="call-row-head">
            <t-space size="small">
              <t-tag theme="primary" variant="light">{{ stageText[c.stage] || c.stage }}</t-tag>
              <t-tag :theme="callStatusTheme[c.status] || 'default'" variant="light">
                {{ callStatusText[c.status] || c.status }}
              </t-tag>
              <span class="review-meta">{{ c.model }}</span>
            </t-space>
            <span class="review-meta">{{ fmtTime(c.insert_time) }}</span>
          </div>
          <div class="call-row-meta">
            耗时 {{ fmtSec(c.duration_ms) }} · token {{ c.total_tokens.toLocaleString() }}（提示
            {{ c.prompt_tokens }} / 生成 {{ c.completion_tokens }}）
          </div>
          <div v-if="c.error" class="call-error">{{ c.error }}</div>
        </div>
      </t-loading>
    </t-drawer>

    <!-- 人工标注 / 校正抽屉 -->
    <EnrichCuratorDrawer
      :visible="curatorVisible"
      :problem-id="curatorProblemId"
      :initial-task-type="curatorTaskType"
      :review-mode="curatorReviewMode"
      @saved="onCuratorSaved"
      @rejected="onCuratorRejected"
      @update:visible="onCuratorVisibleChange"
    />

    <!-- 驳回理由对话框 -->
    <t-dialog
      v-model:visible="rejectDialogVisible"
      header="驳回标注"
      :confirm-loading="reviewSubmitting"
      @confirm="confirmReject"
    >
      <p>驳回后该标注不生效，会留在失败/待处理记录中，可后续重判。请填写驳回理由（可选，留痕给后续优化 prompt）：</p>
      <t-textarea v-model="rejectNote" :autosize="{ minRows: 3 }" placeholder="驳回理由（可选）" />
    </t-dialog>

    <!-- 合并对话框（目标远程搜索） -->
    <t-dialog
      v-model:visible="mergeDialogVisible"
      header="合并标签"
      :confirm-on-enter="false"
      :confirm-loading="mergeSubmitting"
      @confirm="handleMergeSubmit"
    >
      <p v-if="mergeSource">
        将标签「<b>{{ mergeSource.name }}</b>」的全部题目关联与别名并入目标标签；源标签置为「已合并」并保留指向，历史关联不丢失。
      </p>
      <t-select
        v-model="mergeTargetId"
        :options="mergeTargetOptions"
        :loading="mergeSearching"
        :filterable="true"
        clearable
        placeholder="输入标签名搜索合并目标（正式标签）"
        @search="searchMergeTarget"
      />
    </t-dialog>

    <!-- 别名对话框 -->
    <t-dialog v-model:visible="aliasDialogVisible" header="标签别名管理" :footer="false" width="560px">
      <p v-if="aliasTag">标签「<b>{{ aliasTag.name }}</b>」的归一别名（AI/人工输出这些词时直接映射到该标签）：</p>
